function simplexNoise3D(x, y, z):
    // Skew input space
    s = (x + y + z) / 3
    i = floor(x + s)
    j = floor(y + s)
    k = floor(z + s)

    // Unskew cell origin
    t = (i + j + k) / 6

    // Calculate gradient contributions
    return gradient(i, j, k, x-i+t, y-j+t, z-k+t)
